export default `.page-container{padding:4rem 2rem;max-width:1200px;margin:0 auto;font-family:Poppins,sans-serif;min-height:70vh}.page-header{text-align:center;margin-bottom:3rem}.page-header h2{color:#1b4332;font-size:2.5rem;margin-bottom:.5rem}.page-header p{color:#666;font-size:1.1rem}.product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:2rem}.product-card{background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 4px 15px #0000000d;transition:transform .3s ease;cursor:pointer;position:relative;border:1px solid #eee;display:flex;flex-direction:column}.product-card:hover{transform:translateY(-5px);box-shadow:0 8px 25px #0000001a}.badge{position:absolute;top:10px;left:10px;padding:4px 10px;color:#fff;font-weight:700;font-size:.8rem;border-radius:6px;z-index:10}.badge.top{background:#f1a81b;color:#111}.badge.new{background:#3498db}.img-container{height:220px;background:#fff;display:flex;align-items:center;justify-content:center;border-bottom:1px solid #f5f5f5;padding:1rem}.img-container img{max-height:100%;max-width:100%;object-fit:contain}.card-info{padding:1.5rem;text-align:center;display:flex;flex-direction:column;flex:1}.cat-label{display:block;font-size:.75rem;color:#c76929;font-weight:700;margin-bottom:5px}.card-info h3{margin:0 0 10px;color:#111;font-size:1.1rem;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;flex:1}.price{font-size:1.4rem;color:#1b4332;margin-bottom:15px}.price strong{color:#e74c3c}.add-btn{background-color:#1b4332;color:#fff;border:none;padding:12px;border-radius:8px;cursor:pointer;width:100%;font-weight:700;transition:.2s;margin-top:auto}.add-btn:hover{background-color:#40916c}.empty-state{text-align:center;padding:4rem;color:#999;font-size:1.2rem;font-style:italic}.global-toast{position:fixed;top:80px;right:20px;background:#166534;color:#fff;padding:14px 24px;border-radius:8px;font-family:Poppins,sans-serif;font-weight:600;font-size:.95rem;box-shadow:0 10px 25px #1665344d;z-index:10000;cursor:pointer;border-left:5px solid #4ade80;animation:slideInRight .3s cubic-bezier(.175,.885,.32,1.275);transition:opacity .2s}.global-toast:hover{opacity:.85}.scroll-to-top-btn{position:fixed;bottom:40px;right:40px;width:50px;height:50px;background-color:#64646480;color:#fff;border:none;border-radius:50%;font-size:1.5rem;font-weight:700;cursor:pointer;z-index:9999;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 10px #0000001a;transition:background-color .3s ease,transform .2s ease}.scroll-to-top-btn:hover{background-color:#646464d9;transform:translateY(-3px)}.scroll-to-top-btn:active{transform:translateY(0)}@media (max-width: 768px){.scroll-to-top-btn{bottom:20px;right:20px;width:45px;height:45px}}@keyframes slideInRight{0%{transform:translate(120%);opacity:0}to{transform:translate(0);opacity:1}}@media (max-width: 640px){.global-toast{top:20px;right:10px;left:10px;text-align:center}}
`;